IG$._source = "viewer";

IG$.showLoginProc = function(instance) {
	var me = this,
		lform = $('#loginWindow', instance.target),
		uid = $("#userid", instance.target);
	lform.hide();
}

IG$.$loadApp = function(instance, tmpl) {
	var mainview,
		viewport = instance.viewport;
	
	if (ig$.theme_id)
	{
		ig$.echarts_theme = ig$.theme_id;
	}

	if (instance.__1m/*viewportpanel*/)
	{
		setTimeout(function(){
			$("#loading", instance.target).fadeOut({
				complete: function() {
					$(this).remove();
				}
			});
			$("#loading-mask", instance.target).fadeOut({
				complete: function() {
					$(this).remove();
				}
			});
		}, (IG$.__ep ? 0 : 100));
		
		return;
	}
	
	instance.mainPanel = new IG$.MainPanel({
		name: "_I7d",
		instance: instance
	});

	mainview = new $s.panel({
		instance: instance,
		layout: {
			type: "vbox",
			align: "stretch"
		},
		items:[ 
			{
				xtype: "container",
				name: "maintab",
				border: 1,
				flex: 1,
				layout: "fit",
				items: [
					instance.mainPanel
				]
			}
		]
	});

	viewport.add(mainview);
	viewport.doLayout();
	
	instance.__1m/*viewportpanel*/ = mainview;
	
	setTimeout(function(){
		$("#loading", instance.target).fadeOut({
			complete: function() {
				$(this).remove();
			}
		});
		$("#loading-mask", instance.target).fadeOut({
			complete: function() {
				$(this).remove();
			}
		});
		
		instance.$load_init();
		
		if (ig$._load_obj && ig$._load_obj["objid"])
		{
			instance.open_url({
				objid: ig$._load_obj["objid"]
			}, new IG$.callBackObj(me, function() {
				viewport.validateLayout();
			}));
		}
		else if (ig$._load_obj && ig$._load_obj["jobid"])
		{
			instance.open_url({
				jobid: ig$._load_obj["jobid"]
			}, new IG$.callBackObj(me, function() {
				viewport.validateLayout();
			}));
		}
		else if (ig$._load_obj && ig$._load_obj["slink"])
		{
			var req = new IG$._rpc$();

			req.init(null, 
				{
					ack: "sch_res",
					payload: {
						slink: ig$._load_obj["slink"]
					},
					mbody: {option: "sch_res"}
				}, null, 
				function(jdoc){
					var jid = jdoc.opt_1,
						sid = jdoc.opt_3;

					instance.open_url({
						jobid: jid + ":" + sid
					});
				}
			);

			req.send();
		}
		else if (ig$.viewer_menu)
		{
			$.ajax({
				type: "GET",
				url: ig$.viewer_menu + "?_d=" + IG$.getUniqueKey(), 
				dataType: "json",
				timeout: 10000,
				success: function(data) {
					if (data.menus)
					{
						var d_nav = $("#d_nav");
						
						$("#content").mouseover(function() {
							$("#slide_menu").slideUp(400);
							$("#nav > ul > li > ul").fadeOut(300);
						});
						
						$.each(data.menus, function(i, dmenu) {
							var l_nav = $("<li></li>").appendTo(d_nav),
								l_mn = $("<a>" + dmenu.name + "</a>").appendTo(l_nav);
							
							l_mn.mouseover(function(){	  
								if (dmenu.menus && dmenu.menus.length) {
									var idx = $(this).parent("li").children("ul").children("li").size() - 1;
									var sHeight = (idx == 0 ? 75 : idx * 20 + 78);
									$("#slide_menu").css("height", sHeight+"px");

									$("#nav > ul > li > ul").hide();
									$("#slide_menu").slideDown(300);
									$(this).parent("li").children("ul").fadeIn(300).siblings().children("ul").fadeOut(200);
								}
								else
								{
									$("#slide_menu").slideUp(400);
									$("#nav > ul > li > ul").fadeOut(300);
								}
							});
							
							l_mn.click(function(e) {
								e.preventDefault();
								e.stopPropagation();
								
								$("#title_area > h1").text($(this).text());
								
								instance.open_url(dmenu);
							});
							
							if (dmenu.menus && dmenu.menus.length)
							{
								var sul = $("<ul></ul>").appendTo(l_nav);
								$.each(dmenu.menus, function(j, smenu) {
									var s_lav = $("<li><a>" + smenu.name + "</a></li>").appendTo(sul);
									s_lav.click(function(e) {
										e.preventDefault();
										e.stopPropagation();
										
										$("#title_area > h1").text(dmenu.name + " > " + smenu.name);
										
										$("#slide_menu").slideUp(400);
										$("#nav > ul > li > ul").fadeOut(300);
										
										instance.open_url(smenu);
									});
								});
							}
						});
					}
				},
				error: function(e, status, thrown) {
				}
			});
		}
		else if (instance.config && instance.config.target)
		{
			// do nothing
		}
		else
		{
			// loading from resources
			var me = this,
				req = new IG$._rpc$(),
				uid = "/SYS_Config/dashboardmenu";
			
			req.showerror = false;
			req.init(me, 
				{
					ack: "content",
					payload: {uid: uid},
					mbody: {}
				}, me, function(jdoc) {
					if (jdoc.menustructure)
					{
						var d_nav = $("#d_nav");
						
						$("#content").mouseover(function() {
							$("#slide_menu").slideUp(400);
							$("#nav > ul > li > ul").fadeOut(300);
						});
						
						$.each(jdoc.menustructure, function(i, dmenu) {
							var l_nav = $("<li></li>").appendTo(d_nav),
								l_mn = $("<a>" + dmenu.name + "</a>").appendTo(l_nav);
							
							l_mn.mouseover(function(){	  
								if (dmenu.items && dmenu.items.length) {
									var idx = $(this).parent("li").children("ul").children("li").size() - 1;
									var sHeight = (idx == 0 ? 75 : idx * 20 + 78);
									$("#slide_menu").css("height", sHeight+"px");

									$("#nav > ul > li > ul").hide();
									$("#slide_menu").slideDown(300);
									$(this).parent("li").children("ul").fadeIn(300).siblings().children("ul").fadeOut(200);
								}
								else
								{
									$("#slide_menu").slideUp(400);
									$("#nav > ul > li > ul").fadeOut(300);
								}
							});
							
							l_mn.click(function(e) {
								e.preventDefault();
								e.stopPropagation();
								
								if (dmenu.options && dmenu.options.ltype == "report" && dmenu.options.rptl_uid)
								{
									$("#title_area > h1").text(dmenu.options.rptl || $(this).text());
									instance.open_url({
										uid: dmenu.options.rptl_uid
									});
								}
							});
							
							if (dmenu.items && dmenu.items.length)
							{
								var sul = $("<ul></ul>").appendTo(l_nav);
								$.each(dmenu.items, function(j, smenu) {
									var s_lav = $("<li><a>" + smenu.name + "</a></li>").appendTo(sul);
									s_lav.click(function(e) {
										e.preventDefault();
										e.stopPropagation();
										
										$("#title_area > h1").text(dmenu.name + " > " + smenu.name);
										
										$("#slide_menu").slideUp(400);
										$("#nav > ul > li > ul").fadeOut(300);
										
										instance.open_url(smenu);
									});
								});
							}
						});
						
						var smenu = jdoc.menustructure[0];
						
						if (smenu && smenu.options && smenu.options.ltype == "report" && smenu.options.rptl_uid)
						{
							$("#title_area > h1").text(smenu.options.rptl);
							instance.open_url({
								uid: smenu.options.rptl_uid
							});
						}
					}
				});
			req.send(instance);
		}
	}, 50);
};

IG$._load_viewer_cnt = function(instance, jdoc) {
	//check out server login proc
	//var xmlmessage = IG$.toXMLString(xdoc),
	var islogin = false;
	
	if (jdoc && jdoc.uuid)
	{
		islogin = true;
		
		instance.dlgLogin.uuid = jdoc.uuid; 
		
		instance.dlgLogin.mts = {
			sid: jdoc.mts,
			name: jdoc.mts_name
		};
		
		IG$._g$a = instance.dlgLogin.mts.sid; 
		
		if (window.m$mts && instance.dlgLogin.mts.name != window.m$mts && instance.dlgLogin.mts.sid != window.m$mts)
		{
			IG$.showLogout(new IG$.callBackObj(this, function() {
				IG$.showLoginProc(instance);
			}));
			return;
		}
		
		instance.dlgLogin.lastLogin = jdoc;
		
		if (instance.mainPanel)
		{
			instance.mainPanel.updateLoginInfo.call(instance.mainPanel);
		}
		instance.dlgLogin.getUserDetail.call(instance.dlgLogin, false);
	}
	
	if (islogin == false)
	{
		IG$.showLogin(instance, new IG$.callBackObj(this, function() {
			IG$.showLoginProc(instance);
		}), 0);
	}
}

IG$.createRegion = function(instance) {
	var viewport = new $s.viewport({
		instance: instance,
		layout: "fit",
		container: instance.target[0]
	});
	
	viewport.doLayout();
	
	instance.viewport = viewport;
	
	var qstring = window.location.search,
		qmap = {},
		qtemp,
		i, k, v,
		t;
	
	if (qstring && qstring.length)
	{
		qtemp = qstring.split("&");
		if (qtemp.length > 0)
		{
			for (i=0; i < qtemp.length; i++)
			{
				t = qtemp[i];
				
				if (t.indexOf("=") > 0)
				{
					k = t.substring(0, t.indexOf("="));
					v = t.substring(t.indexOf("=") + 1);
					
					if (k.charAt(0) == "?")
					{
						k = k.substring(1);
					}
					
					qmap[k] = v;
				}
			}
		}
	}
	
	ig$._load_obj = qmap;
	
	var req = new IG$._rpc$();
	
	if (qmap["obj_key"])
	{
		req.init(null, 
			{
				ack: "apphelp",
				payload: {},
				mbody: {option: "get_share_key", obj_key: qmap["obj_key"], mts: (window.m$mts || ""), lang: (window.useLocale || "")}
			}, null, 
			function(jdoc) {
				qmap.obj_info = jdoc;

				if (window.m$mts != jdoc.mts)
				{
					window.m$mts = jdoc.mts;
				}
				
				if (jdoc["public"] =="T")
				{
					req = new IG$._rpc$();
					req.init(null, 
						{
							ack: "apphelp",
							payload: {},
							mbody: {option: "get_share_sec", obj_key: qmap["obj_key"], mts: (window.m$mts || ""), lang: (window.useLocale || "")}
						}, null, 
						function(jdoc) {
							IG$._g$a = jdoc._mts_;
							IG$._share_uid_ = jdoc.token;

							ig$._load_obj = {
								objid: qmap.obj_info.uid
							};
							
							IG$.$loadApp();
							/* load report after everything is ready
							instance.open_url({
								objid: qmap.obj_info.uid
							});
							*/
						},
						function(){
							IG$.showLogin(instance, new IG$.callBackObj(this, function() {
								IG$.showLoginProc(instance);
							}), 0);
							return true;
						});
					
					req.send(instance);
				}
				else
				{
					req = new IG$._rpc$();
					req.init(null, 
						{
							ack: "helpcontent",
							payload: {},
							mbody: {option: "loginstatus", mts: (window.m$mts || ""), lang: (window.useLocale || "")}
						}, null, 
						function(jdoc) {
							IG$._load_viewer_cnt(instance, jdoc);
						},
						function(){
							IG$.showLogin(instance, new IG$.callBackObj(this, function() {
								IG$.showLoginProc(instance);
							}), 0);
							return true;
						});
					
					req.send(instance);
				}
			},
			function(){
				IG$.showLogin(instance, new IG$.callBackObj(this, function() {
					IG$.showLoginProc(instance);
				}), 0);
				return true;
			});
		
		req.send(instance);
	}
	else
	{
		req.init(null, 
			{
				ack: "helpcontent",
				payload: {},
				mbody: {option: "loginstatus", mts: (window.m$mts || ""), lang: (window.useLocale || "")}
			}, null, 
			function(jdoc) {
				IG$._load_viewer_cnt(instance, jdoc);
			},
			function(){
				IG$.showLogin(instance, new IG$.callBackObj(this, function() {
					IG$.showLoginProc(instance);
				}), 0, null, instance);
				return true;
			});
		
		req.send(instance);
	}
};

IG$.createInstance = function(instance) {
	var target = ig$.mainview || '#mainview',
		progressbar;
	
	target = instance.target || target;
	
	instance.target = $(target);
	
	progressbar = $("#lpt", $("#loading", instance.target));
	
	progressbar.css("width", "80%");
	
	if (!webix.env.touch) //  && webix.ui.scrollSize)
		webix.CustomScroll.init();
	
	IRm$.r2/*loadResources*/({
		func: function() {
			progressbar.css("width", "100%");
			
			setTimeout(function() {
				var i,
					copt;
					
				IG$.loadExtend.rcsloaded = true;
				
				copt = {
					closeText: IRm$.r1("L_C_CLOSE"),
					prevText: IRm$.r1("L_C_PREV"),
					nextText: IRm$.r1("L_C_NEXT"),
					currentText: IRm$.r1("L_C_CUR"),
					monthNames: IRm$.r1("L_C_M_NAMES").split("#"),
					monthNamesShort: IRm$.r1("L_C_M_NAMES_S").split("#"),
					dayNames: IRm$.r1("L_C_D_NAMES").split("#"),
					dayNamesShort: IRm$.r1("L_C_D_NAMES_S").split("#"),
					dayNamesMin: IRm$.r1("L_C_D_NAMES_M").split("#"),
					weekHeader: IRm$.r1("L_C_W_H"),
					firstDay: 0,
					isRTL: false,
					showMonthAfterYear: true,
					yearSuffix: IRm$.r1("L_C_YR_SFX"),
					c1disp: "yyyy-mm-dd",
					c1format: "yy-mm-dd",
					c2disp: "yyyy-mm",
					c2format: "yy-mm"
				};
				
				$.datepicker.setDefaults(copt);
				
				IG$.calendar_locale = copt;
				
				$.each(IG$.loadExtend.items, function(i, obj) {
					IG$.extend(obj.name, obj.base, obj.option);
				});
				
				$.each(IG$.filteropcodes, function(i, obj) {
					var l = obj.lcode;
					obj.locale = IRm$.r1(l);
				});
				
				var uid = $.cookie("lui") || "";
				var upd = "";
				
				instance.dlgLogin = new IG$.sessionUtils({instance: instance});
				
				instance.dlgLogin.callback = new IG$.callBackObj(this, function() {
					IG$.showLoginProc(instance);
				});
		
				IG$.createLoginPanel(instance, uid, upd, true, instance);
				IG$.loadMapData();
	
				IG$.createRegion(instance);
			}, 300);
		}
	});
}


