IG$.objectAuth = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: "fit",
	
	closable: false,
	resizable:false,
	width: 560,
	height: 400,
	
	_confirm: function() {
		this.updateAuthConfig();
	},
	
	updateAuthConfig: function() {
		var panel = this,
			req = new IG$._rpc$(),
			content,
			updateall = panel.down('[name=updateall]').getValue(),
			updateappend = panel.down("[name=updateappend]").getValue(),
			dgrid = panel.down("[name=datagridview]"),
			items = dgrid.store.data.items,
			record,
			i, d;
			
		content = {
			option: "update",
			updateall: updateall,
			updateappend: updateappend,
			auths: []
		};
		
		for (i=0; i < items.length; i++)
		{
			record = items[i];
			d = record.data;
			
			content.auths.push({
				sid: d.sid,
				readable: d.readable,
				writable: d.writable,
				manage: d.manage,
				revoke_readable: d.revoke_readable,
				revoke_writable: d.revoke_writable
			});
		}
		
		req.init(panel, 
			{
				ack: "authcontent",
				payload: {uid: this.uid, type: this.itemtype},
				mbody: content,
				meta_type: "auth_req"
			}, panel, panel.rs_updateAuthConfig, null);
		req.send();
	},
	
	rs_updateAuthConfig: function(xdoc) {
		var me = this;
		IG$.alertmsg(ig$.appname, IRm$.r1("M_SUCCESS"), null, me, 0, "success");
		me.callback && me.callback.execute();
		me.close();
	},
	
	init_f: function() {
		if (this.uid)
		{
			var panel = this,
				req = new IG$._rpc$();
				
			req.init(panel, 
				{
					ack: "authcontent",
					payload: {uid: this.uid, type: this.itemtype},
					mbody: {option: "standard"}
				}, panel, panel.rs__getAuthInfo, null);
			req.send();
		}
	},
	
	rs__getAuthInfo: function(jdoc) {
		var i,
			data,
			dn;
		
		// mgrid.addEventListener(MecGridEvent.DRAW_COMPLETED, drawCompleteHandler, false, 0, true);
		// mgrid.dataProvider = data.children();
		this.dataset = [];
		
		for (i=0; i < jdoc.length; i++)
		{
			data = jdoc[i];
			
			switch (data.dutytype)
			{
			case "A":
				dn = IRm$.r1("B_DEFAULT");
				break;
			case "C":
				dn = "Custom";
				break;
			case "G":
				dn = "Group";
				break;
			case "U":
				dn = "User";
				break;
			default:
				dn = "Unknown";
				break;
			}
			
			data.dutytype_d = dn;
			
			if (data.dutytype != "A" || data.sid.toLowerCase() != IG$.dutymap[0])
			{
				this.dataset.push(data);
			}
		}
		
		this.down("[name=datagridview]").store.loadData(this.dataset);
	},
	
	initComponent : function() {
		var me = this,
			ltype = me.itemtype.toLowerCase(),
			hassub = ltype == "folder" || ltype == "bobject",
			mcolumns;
		
		me.title = IRm$.r1('T_OBJECT_AUTH');

		// ig$.$l_ = ig$.$l_ || 0;
		
		mcolumns = [
			{
				text: IRm$.r1("B_NAME"),
				flex: 1,
				sortable: false,
				dataIndex: 'name'
			},
			{
				text: IRm$.r1("B_TYPE"),
				width: 60,
				dataIndex: "dutytype_d"
			},
			{
				xtype: 'checkcolumn',
				text: IRm$.r1("B_READ"),
				width: 50,
				sortable: false,
				dataIndex: 'readable',
				editor: {
					xtype: 'checkbox'
				}
			},
			{
				xtype: 'checkcolumn',
				text: IRm$.r1("B_WRITE"),
				width: 50,
				sortable: false,
				dataIndex: 'writable',
				editor: {
					xtype: 'checkbox'
				}
			}
		];
		
		if (hassub) //  && ig$.$l_ < 5)
		{
			mcolumns.push({
				xtype: 'checkcolumn',
				text: IRm$.r1("L_REVOKE_READ"),
				width: 80,
				sortable: false,
				dataIndex: 'revoke_readable',
				editor: {
					xtype: 'checkbox'
				}
			});
			
			mcolumns.push({
				xtype: 'checkcolumn',
				text: IRm$.r1("L_REVOKE_WRITE"),
				width: 80,
				sortable: false,
				dataIndex: 'revoke_writable',
				editor: {
					xtype: 'checkbox'
				}
			});
		}
		
		$s.apply(this, {
			items: [
				{
					xtype: "panel",
					layout: {
						type: 'vbox',
						align: 'stretch'
					},
					
					border: false,
					bodyPadding: ig$.padding,
					
					items: [
						{
							xtype: 'displayfield',
							value: IRm$.r1('L_AU_TITLE')
						},
						{
							xtype: "container",
							layout: {
								type: "hbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "textfield",
									labelWidth: 80,
									name: "t_keyword",
									emptyText: IRm$.r1("L_SEARCH_KWD"),
									fieldLabel: IRm$.r1("B_SEARCH"),
									enableKeyEvents: true,
									listeners: {
										keyup: function(tobj, e, eopts) {
											e.keyCode == 13 && IG$._dofilter(this, "datagridview", ["name", "type"], tobj);
										},
										scope: this
									}
								},
								{
									xtype: "button",
									iconCls: "icon-toolbar-search",
									tooltip: IRm$.r1("B_SEARCH"),
									handler: function() {
										IG$._dofilter(this, "datagridview", ["name", "type"], this.down("[name=t_keyword]"));
									},
									scope: this
								},
								{
									xtype: "container",
									flex: 1
								}
							]
						},
						{
							xtype: "gridpanel",
							name: "datagridview",
							
							store: {
								fields: [
									"name", "readable", "writable", "manage", "uid", "nodepath", "type", "sid", "dutytype_d", "dutytype"
								]
							},
							
							flex: 1,
							border: 1,
							columns: mcolumns,
							listeners: {
								checkchange: function(rec, state, column) {
									switch (column)
									{
									case "revoke_readable":
										state && rec.set("readable", false);
										state && rec.set("writable", false);
										state && rec.set("revoke_writable", true);
										break;
									case "revoke_writable":
										state && rec.set("writable", false);
										break;
									case "readable":
										state && rec.set("revoke_readable", false);
										state && rec.set("revoke_writable", false);
										// state && rec.set("writable", false);
										break;
									case "writable":
										state && rec.set("revoke_readable", false);
										state && rec.set("reovke_writable", false);
										state && rec.set("readable", true);
										break;
									}
								},
								scope: this
							}
						},
						{
							xtype: "container",
							height: 10
						},
						{
							xtype: "container",
							layout: {
								type: "hbox",
								align: "stretch"
							},
							hidden: !hassub,
							items: [
								{
									name: 'updateall',
									fieldLabel: IRm$.r1('B_OPTION'),
									xtype: 'checkbox',
									boxLabel: IRm$.r1('L_AU_APPLY_SUB'),
									checked: false
								},
								{
									name: 'updateappend',
									xtype: 'checkbox',
									// hidden: ig$.$l_ > 5,
									boxLabel: IRm$.r1('L_AU_APPLY_APPEND'),
									checked: false
								}
							]
						}
					]
				}	
			],
			buttons:[
				{
					text: IRm$.r1("L_SUBSCRIBE"),
					hidden: ig$.features["ig_n_osubscr"] !== false, // || ig$.$l_ > 5,
					handler: function() {
						var me = this,
							dlgpop;
						dlgpop = new IG$.objectSubscribe({
							instance: me.instance,
							uid: me.uid, 
							itemtype: me.itemtype
						});
						
						IG$.checkLogin(me, dlgpop);
					},
					scope: this
				},
				"->",
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					var panel = this;
					
					panel.init_f();
				}
			}
		});
		
		IG$.objectAuth.superclass.initComponent.apply(this, arguments);
	}
});