/***********************************************************************
 * AppPageControl: Checkbox 
 */
 IG$.ctrlCheckbox = IG$.extend(IG$.ctrlBase, {
	type: "checkbox",
	initComponent: function() {
		var me = this;
		me.p.push(
			{name: "fieldlabel", type: "property", datatype: "string"},
			{name: "label_names", type: "property", datatype: "string"},
			{name: "value_names", type: "property", datatype: "string"},
			{name: "name_delimiter", type: "property", datatype: "string", value: ";"},
			{name: "check_type", type: "property", datatype: "string", value: "checkbox", 
				"enum": [
					{name: "checkbox", value: "checkbox"},
					{name: "radio", value: "radio"}
				]
			},
			{name: "change", type: "event"}
		);
		
		me.viewer = null;
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	initDrawing: function () {
		var me = this,
			fid = me._get_id();

		var tmpl = me._getTmpl(fid);

		me.el$.addClass("form-outline");
		me.tl$ && me.tl$.hide();
		me.mp$dv = $(tmpl).appendTo(me.el$);
		me.mp$ = new mdc.checkbox.MDCCheckbox(me.mp$dv[0]);
		$("input", me.mp$dv).change(function(ev, dt) {
			me.trigger("change_val", fitem.updateValues == true);
		});
		
		me.superclass.prototype.initDrawing.call(me);
	},
	invalidate: function () {
	},
	
	commit: function() {
		var me = this;
	},
	
	updateProperty: function(kname, value) {
		var me = this;
		
		switch (kname)
		{
		case "text":
			
			break;
		case "label_names":
		case "value_names":
		case "name_delimiter":
		case "check_type":
			clearTimeout(me._vtimer);
			me._vtimer = setTimeout(function() {
				me._setData();
			}, 20);
			break;
		}
	},
	
	getSelectionData: function(itemname) {
		var me = this,
			_dp = me._dp,
			value = [],
			i, d, c,
			is_radio = me.property.check_type == "radio";
		
		if (_dp)
		{
			for (i=0; i < _dp.length; i++)
			{
				d = _dp[i];
				c = d.el$;
				if (c && c.checked)
				{
					value.push({
						code: c.code,
						text: c.text
					});

					if (is_radio)
						break;
				}
			}
		}
		
		return value;
	},
	
	applyDataSet: function(value) {
		var data = value.data,
			i, result = {
				data: []
			}, dp = result.data;
		
		me.loadData(result);
	},
		
	_setData: function() {
		var me = this,
			result = {
				data: []
			},
			i, delim, values, labels,
			property = me.property, m,
			rdata = result.data;
			
		labels = property.label_names || "";
		values = property.value_names || "";
		delim = property.name_delimiter || ";";
		
		labels = labels.split(delim);
		values = values.split(delim);
		
		m = Math.max(labels.length, values.length);
		
		for (i=0; i < m ; i++)
		{
			rdata.push({
				code: values[i] || labels[i],
				text: labels[i] || values[i]
			});
		}
		
		me.loadData(result);
	},
	
	loadData: function(result) {
		var me = this,
			el$ = me.el$,
			property = me.property,
			lname = "radio_" + me._get_id();

		el$.empty();
		me._dp = result;

		
			
		$.each(result.data, function(i, p) {
			if (p.code || p.text)
			{
				var fid = me._get_id();
				var tmpl = me._getTmpl(fid, p.text || p.code);
				var m = $(tmpl).appendTo(el$);
				p.el$ = new mdc.checkbox.MDCCheckbox(m[0]);
			}
		});
	},

	_getTmpl: function(fid, label) {
		var tmpl = ['<div class="mdc-form-field">',
			'<div class="mdc-checkbox">',
			'  <input type="checkbox"',
			'		 class="mdc-checkbox__native-control"',
			'		 id="' + fid + '"/>',
			'  <div class="mdc-checkbox__background">',
			'	<svg class="mdc-checkbox__checkmark"',
			'		 viewBox="0 0 24 24">',
			'	  <path class="mdc-checkbox__checkmark-path"',
			'			fill="none"',
			'			d="M1.73,12.91 8.1,19.28 22.79,4.59"/>',
			'	</svg>',
			'	<div class="mdc-checkbox__mixedmark"></div>',
			'  </div>',
			'  <div class="mdc-checkbox__ripple"></div>',
			'</div>',
			'<label for="' + fid + '">' + (label || '') + '</label>',
		  '</div>'].join("\n");
		return tmpl;
	}
});

IG$.controls.checkbox = new IG$.ctrlCheckbox({}, null);