/*
 * Blank Panel Control
 */
IG$.rfBlankPanel = function (instance, container, sop) {
	var me = this;
	
	me.instance = instance;
	me.container = container;
	me.sheetoption = sop;
	
	me.updateValues = true;
	
	me.$init();
};

IG$.rfBlankPanel.prototype = {
	$init: function() {
		var me = this,
			values = {},
			browser;
		
		me.contentarea = $("<div></div>").appendTo(me.container);

		if (me.owner && me.owner.box)
		{
			me.owner.box.bind("updatecomplete", function() {
				me.validateItems();
			});
		}
	},
	
	removeObj: function() {
	},
	
	validateItems: function() {
		var me = this,
			owner = me.owner,
			dobj = (owner && owner.docitems && me.sheetoption ? owner.docitems[me.sheetoption.docid] : null),
			n=0,
			bf = false,
			i;
			
		if (dobj && dobj.children)
		{
			$.each(dobj.children, function(i, item) {
				if (item.docid)
				{
					var di = owner.bodylist[item.docid];
					n++;
				}
			});
		}
	},
	
	setSize: function(w, h) {
		var me = this,
			c = me.contentarea;
		
		IG$.j$ext._w(c, w);
		IG$.j$ext._h(c, h);
	},
	
	updateFilterContent: function(finfo) {
	}
};
