IG$.cVis._highcharts = $s.extend(IG$.cVis.base, {
	drawmode: "_modc_",

	render: function(drawchart, mresult) {
		var me = this,
			mcr = me.chart_option,
			rcs = mcr.subtype,
			_chartview = me.chartview;
		
		$.each(drawchart, function(i, d) {
			var masterChart;
			var n,
				chartoption = me.sheetoption ? me.sheetoption.model.chart_option : null,
				charttype = chartoption ? chartoption.subtype : null,
				tnodes; //, function(masterChart) {me.createDetail(masterChart)});
			
			masterChart = new Highcharts.Chart(d),
			_chartview._masterCharts.push(masterChart);
			
			me.__sel_s = null;
			
			if (mresult && mresult.__bands && mresult.__bands.length)
			{
				tnodes = mresult.__bands;
				for (n=0; n < tnodes.length; n++)
				{
					_rpc.drawBand.call(_rpc, masterChart, tnodes[n], charttype, _chartview);
				}
			}
			else if (d.__cf && d.__cf.length)
			{
				_rpc.curveFit.call(_rpc, masterChart, d.__cf, charttype, _chartview);
			}
		});

        IG$.cVis._highcharts.superclass.render.apply(me, arguments);
	},

    updatedisplay: function(w, h) {
        var me = this,
            _chartview = me.chartview,
            _masterCharts = _chartview._masterCharts;

        if (_masterCharts && _masterCharts.length > 0)
		{
			if (pielayout == "h")
			{
				tw = w / _masterCharts.length;
				th = h;
			}
			else if (pielayout == "h")
			{
				th = h / _masterCharts.length;
				tw = w;
			}
			else
			{
				tw = w;
				th = h;
			}

			// for (i=0; i < _masterCharts.length; i++)
			$.each(_masterCharts, function(i, mchart) {
				$(mchart.renderTo).css({
					position: "absolute",
					left: (pielayout == "h" ? tw * i : 0),
					top: (pielayout == "v" ? th * i : 0),
					width: tw,
					height: th
				});

				mchart.setSize.call(mchart, tw, th, doAnimation = true);
				mchart.renderTo && $(mchart.renderTo).hide().show(0);
			});
		}
    }
});