	_proc_bpmn: function(executeEvents, event_action, callback) {
		var me = this,
			event = event_action.event,
			params = event.params,
			iparams = params.iparams,
			oparams = params.oparams,
			idata, idatamap = {},
			k, vd, oparam,
			p1, r1,
			exeres = {},
			cnt = {},
			haserror;

		me.setLoading(false);

		r1 = {resultmap: {}};

		for (k in oparams)
		{
			oparam = oparams[k];
			v = me.procGetParamValue(oparam);

			if (v.maptype == "ctrl")
			{
				v.ctrl && v.ctrl.clearInvalid();
			}

			if (!v.value && oparam.required !== false)
			{
				if (v.maptype == "ctrl")
				{
					haserror = 1;
					v.ctrl && v.ctrl.markInvalid();
				}
			}
			
			cnt[k] = v ? v.value : null;
		}

		if (haserror)
		{
			me._close_actions(executeEvents);
		}
		else
		{
			me.fireEvent("bpmn_proc", {
				event_action: event_action, 
				params: cnt,
				callback: new IG$.callBackObj(me, function() {
					me._do_next(executeEvents, event_action, callback);
				})
			});
		}

		return exeres;
	},

