	updateEventValue: function(filter) {
		var me = this,
			valuemode,
			ctlvalue,
			i,
			c,
			pmap = me.framecontent.page_param_map;
			
		filter.filtervalue = null;
		
		if (filter.operator)
		{
			valuemode = filter.valuemode;
			if (valuemode == "control")
			{
				var valuectrl = me.ControlDict[filter.valuefield.toLowerCase()];
				
				if (valuectrl)
				{
					ctlvalue = valuectrl.getSelectionData(filter.valuefield);
					
					if (ctlvalue != null)
					{
						filter.filtervalue = ctlvalue;
					}
				}
			}
			else if (valuemode == "value")
			{
				ctlvalue = [
					{code: filter.valuetext}
				];
				filter.filtervalue = ctlvalue;
			}
			
			if (ctlvalue && ctlvalue.length > 0)
			{
				for (i=0; i < ctlvalue.length; i++)
				{
					c = ctlvalue[i].code;
					
					if (c && c.charAt(0) == "{" && c.charAt(c.length-1) == "}")
					{
						c = c.substring(1, c.length - 1);
						if (pmap[c])
						{
							c = pmap[c].get();
							
							ctlvalue[i].code = c;
						}
					}
				}
			}
		}
	},

	procGetParamValue: function(param) {
		var me = this,
			r;

		r = me.procGetParamValueItem(param);

		return r;
	},

	procGetParamValueItem: function(param) {
		var rd = {},
			r,
			me = this,
			framecontent = me.framecontent,
			ctrl, pval,
			ptype = param.maptype;
		
		rd.maptype = ptype;

		if (ptype == "var")
		{
			ctrl = framecontent.page_param_map[param.value];
			rd.ctrl = ctrl;
			r = (ctrl ? ctrl.get() : null);
		}
		else if (ptype == "ctrl")
		{
			if (param.value)
			{
				ctrl = me.ControlDict[param.value.toLowerCase()];
			}
			
			rd.ctrl = ctrl;

			// ctrl && ctrl.control && ctrl.control.commit && ctrl.control.commit();
			// r = (ctrl && ctrl.control ? ctrl.control.get("text") : null);
//				if (ctrl && ctrl.control && ctrl.control.commit)
//				{
//					ctrl.control.commit();
//				}
			
			ctrl.clearInvalid();

			if (ctrl && ctrl.control && ctrl.control.getSelectionData)
			{
				pval = ctrl.control.getSelectionData(param);
				if (pval && pval.length > 0)
				{
					r = pval[0].code;
				}
			}
			else if (ctrl && ctrl.control)
			{
				r = ctrl.control.get("text");
			}
		}

		rd.value = r;
		
		return rd;
	},

