	getInputParams: function(event) {
		var cnt = [],
			k,
			me = this,
			p, v,
			haserror;
		
		if (event.params)
		{
			for (k in event.params.iparams)
			{
				p = event.params.iparams[k];
				v = me.procGetParamValue(p);

				if (v.maptype == "ctrl")
				{
					v.ctrl && v.ctrl.clearInvalid();
				}

				if (p.required && !v.value)
				{
					if (v.maptype == "ctrl")
					{
						haserror = 1;
						v.ctrl && v.ctrl.markInvalid();
					}
				}
				
				cnt.push({
					uid: p.uid,
					name: p.name,
					value: v ? v.value : null
				});
			}
		}
		
		return haserror ? null : cnt;
	},

	
