	validateSize: function() {
		var me = this,
			cntarea = me.dashboardcnt;
		
		if (me._vtimer)
		{
			clearTimeout(me._vtimer);
		}

		me._vtimer = setTimeout(function() {
			if (me._validating)
				return;

			me._validating = true;
			cw = IG$.j$ext._w(cntarea);
			ch = IG$.j$ext._h(cntarea);
			me.fieldlabelwidth = 0;
			void 0;
			me.validateSubSize(null, me.RootControlItems, cw, ch, true);
			me.fieldlabelwidth && me.validateLabelSize(me.RootControlItems);
			me._validating = false;
		}, 10);
	},
	
	validateSubSize: function(pctrl, items, cw, ch, is_root) {
		var i,
			me = this,
			ctrl,
			flex,
			fw, fh,
			hitems = [],
			fhsum = 0,
			dashboardcnt_offset = is_root ? me.dashboardcnt.offset() : pctrl.control.html.offset(),
			coffset,
			contentheight = 0,
			flexheights = 0,
			fheight_map = {};

		$.each(items, function(n, ctrl) {
			if (!ctrl.property.visible)
				return;
			if (ctrl.property.minHeight)
			{
				ctrl.control.el$.css({minWidth: "", minHeight: ctrl.property.minHeight + "px"});
			}
			else
			{
				ctrl.control.el$.css({minWidth: "", minHeight: ""});
			}
			ctrl.control.tl$.css("width", "auto");
			fh = ctrl.property.flexHeight || 0;
			if (fh)
			{
				ctrl.control.html.hide();
				hitems.push(ctrl);
				fhsum += fh;
			}
		});
		
		if (fhsum)
		{
			$.each(items, function(n, ctrl) {
				if (!ctrl.property.visible)
					return;
				cstr = ctrl.control.html;
				flex = ctrl.property.flex || 2;
				fw = Math.floor(cw / me.gridsize * flex);
				cstr[0].style.width = (fw - 2) + "px";
				ctrl.control.invalidate();
				if (ctrl.property.visible && ctrl.property.fieldlabel)
				{
					var lbl_width = ctrl.property.labelwidth || 0;
					me.fieldlabelwidth = Math.max(me.fieldlabelwidth, lbl_width ? lbl_width : ctrl.control.tl$.width());
				}

				if (!ctrl.property.flexHeight)
				{
					coffset = cstr.offset();
					contentheight = Math.max(coffset.top - dashboardcnt_offset.top + cstr.outerHeight(), contentheight);

					if (ctrl.layouts && ctrl.layouts.length)
					{
						var sfw = cstr.width(),
							sfh = cstr.height();
						me.validateSubSize(ctrl, ctrl.layouts, sfw, sfh, false);
					}
				}
			});

			var hall = ch - contentheight;
			void 0;
			var tall = hall / fhsum;
			if (tall > 10)
			{
				$.each(hitems, function(n, ctrl) {
					var cstr = ctrl.control.html;
					cstr.show();
					var fh = ctrl.property.flexHeight,
						ah = Math.floor(fh * tall);
						cstr[0].style.height = ah + "px";
					ctrl.control.invalidate();
					if (ctrl.layouts && ctrl.layouts.length)
					{
						var fw = cstr.width(),
							fh = cstr.height();
						me.validateSubSize(ctrl, ctrl.layouts, fw, fh);
					}
				});
			}
		}
	},

	validateLabelSize: function(items) {
		var me = this,
			fieldlabelwidth = me.fieldlabelwidth,
			i, ctrl;

		for (i=0; i < items.length; i++)
		{
			ctrl = items[i];
			if (ctrl.property.visible && ctrl.property.fieldlabel)
			{
				var lbl_width = ctrl.property.labelwidth || 0;
				ctrl.control.tl$.width(lbl_width || fieldlabelwidth);
			}

			if (ctrl.layouts && ctrl.layouts.length)
			{
				me.validateLabelSize(ctrl.layouts);
			}
		}
	},

