	$load_data: function(data, idx)  {
		var me = this,
			headers = [],
			header_map = {},
			rowfix = data.rowfix,
			colcnt = data.colcnt,
			_tabledata = data._tabledata,
			i, j, c, d;

		for (i=0; i < colcnt; i++)
		{
			for (j=0; j < rowfix; j++)
			{
				c = _tabledata[j][i];
				d = j == 0 ? c.code : d + ":" + c.code;
			}

			headers.push(d);
			header_map[d] = (i+1);
		}

		me._loaded_data = {
			rowfix: rowfix,
			data: data,
			headers: headers,
			header_map: header_map,
			length: _tabledata.length - rowfix
		};

		me._load_data(idx);
	},

	_load_data: function(idx, inc) {
		var me = this,
			_loaded_data = me._loaded_data;

		if (!_loaded_data)
			return;

		if (inc)
		{
			_loaded_data.index = _loaded_data.index || 0;
			idx = _loaded_data.index + inc;

			if (idx < 0 || idx >= _loaded_data.length)
				return;
		}
		
		_loaded_data.index = idx;

		var _tabledata = _loaded_data.data._tabledata,
			rowfix = _loaded_data.rowfix,
			header_map = _loaded_data.header_map,
			row;

		row = _tabledata[rowfix + idx];

		$.each(header_map, function(c, i) {
			var ctrl = me.ControlDict[c.toLowerCase()],
				v = row ? row[i-1].code : null;

			if (ctrl)
			{
				ctrl.control.set("text", v);
			}
		});
	},
	
