IG$.v$anViewer = $s.extend(IG$.v$pnl, {
	sheetobj: null,
	pg: 0,
	pgm: -1,
	pgs: 2000,
	rt: -1,
	df: 6,
	
	sized: true,
	aftsized: false,
	
	layout: "fit",
	
	_init: false,
	
	applyReportResult: function(mresults, olapset, reportoption, sheetoption, lrender) {
		var me = this,
			w, h,
			i,
			rg = me.down("[name=rg]"),
			region = $(".d_analysis", rg.body.dom),
			d_analysis_rg = $(".d_analysis_rg", region),
			d_analysis_empt = $(".d_analysis_empt", region);
			
		d_analysis_rg.hide();
		d_analysis_empt.show();
		
		if (!lrender)
		{
			me.mresults = mresults;
			me.olapset = olapset;
			me.reportoption = reportoption;
			me.sheetoption = sheetoption;
		}
		
		if (!me._init)
		{
			return;
		}
		
		w = me.getWidth();
		h = me.getHeight();
		
		setTimeout(function() {
			if (mresults.r_analysis)
			{
				me.rs_reqAnalysis(mresults.r_analysis);
			}
			else if (me.sized == true)
			{
				me.reqAnalysis();
			}
		}, 10);
	},
	
	reqAnalysis: function() {
		var panel = this,
			olapset = panel.olapset,
			reportoption = panel.reportoption,
			sheetobj = panel.sheetobj,
			doc;
			
		if (olapset && olapset.jobid)
		{
			sheetobj.sheetoption.panelwidth = IG$.j$ext._w(panel._parentdom);
			sheetobj.sheetoption.panelheight = IG$.j$ext._h(panel._parentdom);
			doc = reportoption.getCurrentPivot();
			var req = new IG$._rpc$();
			req.init(panel, 
				{
					ack: "olapservice",
					payload: {
						uid: reportoption.uid,
						jobid: olapset.jobid,
						option: "pivot",
						active: "" + sheetobj.sheetindex,
						pivotresult: "F",
						analysisresult: "T"
					},
					mbody: doc,
					meta_type: panel.meta_type || "report"
				}, panel, panel.rs_reqAnalysis);
			req.send();
		}
	},
	
	rs_reqAnalysis: function(jdoc) {
		var me = this,
			table_data,
			rg = me.down("[name=rg]"),
			region = $(".d_analysis", rg.body.dom),
			d_analysis_rg = $(".d_analysis_rg", region),
			d_analysis_empt = $(".d_analysis_empt", region);
		
		table_data = jdoc ? jdoc.table_data : null;
		
		d_analysis_rg.empty();
		
		d_analysis_empt.hide();

		if (table_data && table_data.length)
		{
			$.each(table_data, function(i, tb) {
				var t_data = [],
					j, k,
					cellcharts = [];
				
				t_data.push("<table class='t_analysis'>");
				$.each(tb.headers, function(j, header) {
					t_data.push("<tr>");
					$.each(header, function(k, cell) {
						t_data.push("<th class='anal-" + cell.stylename + "'" + (cell.colspan ? " colspan='" + cell.colspan + "'" : "") + ">" + (cell.text || "") + "</th>");
					});
					t_data.push("</tr>");
				});
				$.each(tb.rows, function(j, row) {
					t_data.push("<tr>");
					$.each(row, function(k, cell) {
						var tname = null;
						
						if (cell.data && cell.data.xtype == "cellchart")
						{
							tname = "cellchart_" + k;
							
							var cobj = {
								name: tname,
								data: cell.data
							};
							
							cellcharts.push(cobj);
						}
						
						if (cell.stylename == "data")
						{
							t_data.push("<td class='anal-data'" + (cell.colspan ? " colspan='" + cell.colspan + "'" : "") + (tname ? " id='" + tname + "'": "") + ">" + (cell.formatvalue || cell.value || cell.text) + "</td>");
						}
						else
						{
							t_data.push("<td class='anal-" + cell.stylename + "'" + (cell.colspan ? " colspan='" + cell.colspan + "'" : "") + (tname ? " id='" + tname + "'": "")  + ">" + (cell.text || "") + "</td>");
						}
					});
					t_data.push("</tr>");
				});
				
				t_data.push("</table>");
				var p = $(t_data.join("")).appendTo(d_analysis_rg);
				
				if (cellcharts.length)
				{
					$.each(cellcharts, function(i, cobj) {
						var td = $("#" + cobj.name, p);
						
						td.empty();
						
						var cdiv = $("<div></div>").appendTo(td);
						
						var w = 120,
							h = 60,
							names = cobj.data.names,
							data = cobj.data.data,
							opt = {
								type: "bar",
								defaultPixelsPerValue: (names.length ? parseInt(w / names.length) : w)
							};
							
						opt.barWidth = opt.defaultPixelsPerValue;
						
						opt.width = w;
						opt.height = h; 
						opt.tooltipFormat = '{{offset:offset}} {{y:val}}'; //{{value}}';
						
						opt.xvalues = names;
						cdiv.sparkline(data, opt);
					});
				}
				
				if (tb.data && tb.data.xtype == "prediction")
				{
					// append prediction
					var mp = $("<tr></tr>").appendTo(p);
					var m1 = $("<td class='anal-header'>Prediction</td>").appendTo(mp);
					var m2 = $("<td colspan='2'></td>").appendTo(mp);
					
					var mtb = $("<table></table>").appendTo(m2),
						tb_prediction = {
							params: []
						};
					
					for (j=0; j < tb.data.xheaders.length; j++)
					{
						var h = tb.data.xheader_indexes[j],
							dmap;
						
						var mtr = $("<tr></tr>").appendTo(mtb);
						var mtd = $("<td><span>" + tb.data.xheaders[j] + "</span></td>").appendTo(mtr);
						var mtd2 = $("<td></td>").appendTo(mtr);
						
						if (tb.data.doublemap[h])
						{
							dmap = tb.data.doublemap[h];
							var mt = [];
							mt.push("<select name='sinput" + j + "'>");
							for (k in dmap)
							{
								mt.push("<option value='" + dmap[k] + "'>" + k + "</option>");
							}
							t_data.push("</select>");
							var sel = $(mt.join("")).appendTo(mtd2);
							
							tb_prediction.params.push({
								html: sel,
								index: j
							});
						}
						else
						{
							var m = $("<input type='text' name='sinput" + j + "'></input>").appendTo(mtd2);
							tb_prediction.params.push({
								html: m,
								index: j
							});
						}
					}
					
					var mtr = $("<tr></tr>").appendTo(mtb);
					var mtd = $("<td></td>").appendTo(mtr);
					var btn = $("<button>Calculate</button>").appendTo(mtd);
					var mtd2 = $("<td></td>").appendTo(mtr);
					
					btn.bind("click", function() {
						var m = tb.data.params[0],
							i,
							desc = "";
						
						for (i=1; i < tb_prediction.params.length; i++)
						{
							var tval = tb_prediction.params[i-1].html.val();
							tval = Number(tval);
							
							m += tval * tb.data.params[i];
						}
						
						if (tb.data.doublemap[tb.data.ycolumn])
						{
							dmap = tb.data.doublemap[tb.data.ycolumn];
							
							if (dmap)
							{
								var fval = Math.floor(m);
								for (h in dmap)
								{
									if (dmap[h] <=  fval && dmap[h] + 1 > fval)
									{
										desc = h;
										break;
									}
								}
							}
						}
						
						mtd2.html(m + (desc ? " (" + desc + ")" : ""));
					});
				}
			});
			
			d_analysis_rg.show();
		}
		else
		{
			d_analysis_empt.show();
		}
	},
	
	
	_ctrlwindow: function(cmd) {
		var me = this;
	},
	
	init_f: function() {
		var panel = this,
			w = panel.getWidth(),
			h = panel.getHeight(),
			sheet = panel.body.dom,
			canvas = null,
			i;
			
		panel._init = true;
		
		if (panel.mresults)
		{
			panel.applyReportResult(null, null, null, null, true);
		}
	},
	
	initComponent: function() {
		var panel = this;
		
		$s.apply(panel, {
			items: [
				{
					xtype: "panel",
					name: "rmain",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: [
						{
							name: "rg",
							// xtype: "container",
							autoScroll: true,
							scroll: "xy",
							html: "<div class='d_analysis'><div class='d_analysis_rg'></div><div class='d_analysis_empt'><div class='d_analysis_empt_bg></div><span>No Analysis Result Data </span></div></div>"
						}
					]
				}
			]
		});
		
		panel.on("resize", function(p, w, h) {
			panel.CLS.resize.call(panel, w, h);
		});
		panel.on("afterrender", function() {
			panel.CLS.afterrender.call(panel, panel);
		});
		
		IG$.v$anViewer.superclass.initComponent.call(panel);
	},
	
	CLS: {
		resize: function(w, h) {
			var me = this;
			
			if (w > 0 && h > 0)
			{
				me.setPanelSize(w, h);
				
				me.sized = true;
				
				if (me.aftsized == true)
				{
					me.aftsized = false;
				}
			}
		},
		afterrender: function(sender) {
			this.init_f();
		}
	},
		
	setPanelSize: function(w, h) {
		var p = this;
		if (p.rt > -1)
		{
			clearTimeout(p.rt);
		}
		
		p.rt = setTimeout(function() {
		}, 20);
	},
	
	getDrillXML: function() {
		var dinfo = '';
		return dinfo;
	},
	
	getExportData: function(option, startx, starty, filetype, docid, d_width, d_height, callback) {
		var me = this,
			r = {},
			i,
			ix = startx, iy = starty, offset,
			sliceview,
			rview, svg, expdata,
			iw, ih,
			p = me.plotdata,
			gdom = me.rgraphzone;
		
		if (p && p.length > me.pg)
		{
			rview = p[me.pg];
			ix = startx;
			iy = starty;
			iw = IG$.j$ext._w(gdom);
			ih = IG$.j$ext._h(gdom);
			r = {
				type: "chart",
				x: ix,
				y: iy,
				d_width: d_width,
				d_height: d_height,
				width: iw,
				height: ih,
				docid: docid
			};
			if (filetype !== "SVG" && me.crv && me.crv[0] && me.crv[0].toDataURL)
			{
				r.image_data = me.crv[0].toDataURL("image/png");
				r.image_type = "png";
			}
			else
			{
				r.image_data = Base64.encode(me.drPlot(gdom, rview, false).join(""));
				r.image_type = "svg";
			}
			
			callback.execute(r);
		}
		else
		{
			callback.execute(r);
		}
	},
	
	applyOptions: function(rop, sop) {
		var me = this;
		
		if (rop && sop)
		{
			me.reportoption = rop;
			me.sheetoption = sop;
		}
	}
});