IG$.detailDrillWin = $s.extend($s.window, {
	xtype: "window",
	modal: true,
	region:'center',
	layout: "fit",
	closable: true,
	resizable:true,
	maximizable: true,
	width: 700,
	height: 500,
	
	callback: null,
	poolname: null,
	
	confirm: function() {
		var me = this;
	},
	
	initComponent : function() {
		var me = this,
			i,
			pitem,
			rtype,
			doc = $(document),
			w = doc.width() || 700,
			h = doc.height() || 600;
		
		$s.apply(me, {
			width: w - 80,
			height: h - 80,
			title: IRm$.r1("L_DET_VIEW") + " (" + (me.viewinfo.title || me.viewinfo.name) + ")",
			items: [
				{
					xtype: "container",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: [
//						{
//							xtype: "displayfield",
//							value: me.viewinfo.title || me.viewinfo.name
//						},
						{
							xtype: "panel",
							flex: 1,
							border: 0,
							layout: "fit",
							name: "p_main",
							items: [
							]
						}
					]
				}
			],
			buttons: [
				{
					text: IRm$.r1('B_CLOSE'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			]
		});
				
		IG$.detailDrillWin.superclass.initComponent.apply(this, arguments);
	},
	listeners: {
		afterrender: function(tobj) {
			var me = this,
				rtype = "report",
				pitem,
				viewinfo = me.viewinfo,
				p_main = me.down("[name=p_main]");
				
			if (viewinfo)
			{
				pitem = IG$.createAppPanel(
					me.instance, 
					viewinfo.uid,
					rtype, 
					viewinfo.name,
					viewinfo.nodepath, 
					false,
					{
						closable: false, 
						hiddentoolbar: true,
						auxfilter: me.auxfilter,
						header: false
					}
				);
				
				p_main.add(pitem);
			};
		}
	}
});