IG$.explorerSearch = $s.extend($s.window, {
	
	modal: true,
	resizable: false,
	width: 400,
	autoHeight: true,
	bodyPadding: ig$.padding,
	
	layout: {
		type: "vbox",
		align: "stretch"
	},
	
	init_f: function() {
		var me = this,
			sL = me.searchOption,
			fltsetdate = me.down("[name=fltsetdate]"),
			fltfromdate = me.down("[name=fltfromdate]"),
			flttodate = me.down("[name=flttodate]"),
			fltypegrid = me.down("[name=fltypegrid]"),
			tmap = {},
			rec,
			i,
			typelist = [
				{name: IRm$.r1("D_FOLDER"), type: "Folder"},
				{name: IRm$.r1("D_BOBJECT"), type: "BObject"},
				{name: IRm$.r1("D_REPORT"), type: "Report"},
				// ((IG$.level == 1) ? {name: "Dashboard", type: "Dashboard"},
				{name: IRm$.r1("D_METRIC"), type: "Dimension"},
				{name: IRm$.r1("D_MEASURE"), type: "Measure"}
			];
		
		fltypegrid.store.loadData(typelist);
		
		if (sL)
		{
			me.down("[name=keyword]").setValue(sL.keyword);
			fltsetdate.setValue(sL.fltsetdate);
			sL.fltfromdate && fltfromdate.setValue(sL.fltfromdate);
			sL.flttodate && flttodate.setValue(sL.flttodate);
			
			if (sL.typelist && sL.typelist.length > 0)
			{
				for (i=0; i < sL.typelist.length; i++)
				{
					tmap[sL.typelist[i]] = 1;
				}
				
				for (i=0; i < fltypegrid.store.data.items.length; i++)
				{
					rec = fltypegrid.store.data.items[i];
					
					if (tmap[rec.get("type")] == 1)
					{
						rec.set("selected", true);
					}
				}
			}
		}
	},
	
	_confirm: function() {
		var me = this,
			sL = me.searchOption,
			fltsetdate = me.down("[name=fltsetdate]").getValue(),
			fltfromdate = me.down("[name=fltfromdate]").getValue(),
			flttodate = me.down("[name=flttodate]").getValue(),
			fltypegrid = me.down("[name=fltypegrid]"),
			i,
			typelist = [];
		
		for (i=0; i < fltypegrid.store.data.items.length; i++)
		{
			if (fltypegrid.store.data.items[i].get("selected") == true)
			{
				typelist.push(fltypegrid.store.data.items[i].get("type"));
			}
		}
		
		sL.fltsetdate = fltsetdate;
		sL.fltfromdate = fltfromdate ? fltfromdate.getTime() : null;
		sL.flttodate = flttodate ? flttodate.getTime() : null;
		sL.typelist = typelist;
		sL.keyword = me.down("[name=keyword]").getValue();
		
		if (me.callback)
		{
			me.callback.execute();
		}
		me.close();
	},
	
	initComponent : function() {
		var me = this;
		
		me.title = IRm$.r1('I_EXP_SCH');
		
		$s.apply(me, {

			items: [
				{
					xtype: "fieldset",
					title: IRm$.r1("L_FLT_COND"),
					collapsible: false,
					autoHeight: true,
					collapsed: false,
					defaults: {
						labelWidth: 80,
						anchor: "100%",
						layout: "anchor",
						defaults: {
							anchor: "100%"
						}
					},
					items: [
						{
							xtype: "textfield",
							name: "keyword",
							fieldLabel: IRm$.r1("L_KEYWORD")
						},
						{
							xtype: "combobox",
							name: "fltypegroup",
							queryMode: "local",
							displayField: "name",
							valueField: "gcode",
							
							editable: false,
							
							store: {
								fields: [
									"name", "gcode"
								],
								data: [
									{name: IRm$.r1("L_QUICK_SELECT"), gcode: ""},
									{name: IRm$.r1("B_ALL"), gcode: "all"},
									{name: IRm$.r1("D_FOLDER"), gcode: "folder"},
									{name: (IG$.level == 1) ? "Report or dashboard" : IRm$.r1("D_REPORT"), gcode: "report"},
									{name: IRm$.r1("L_ANAL_ITEMS"), gcode: "dimensions"}
								]
							},
							listeners: {
								select: function(combo, records, eOpts) {
									var selvalue = combo.getValue(),
										fltypegrid = this.down("[name=fltypegrid]"),
										store = fltypegrid.store,
										i,
										mtype,
										mkey = null,
										regex = null;
									
									switch (selvalue)
									{
									case "all":
										mkey = null;
										break;
									case "report":
										mkey = "Report|Dashboard";
										break;
									case "folder":
										mkey = "Folder";
										break;
									case "dimensions":
										mkey = "Dimension|Measure";
										break;
									}
									
									if (mkey != null)
									{
										regex = new RegExp(mkey);
									}
									
									for (i=0; i < store.data.items.length; i++)
									{
										mtype = store.data.items[i].get("type");
										if (mkey == null || (regex != null && regex.test(mtype) == true))
										{
											store.data.items[i].set("selected", true);
										}
										else
										{
											store.data.items[i].set("selected", false);
										}
									}
								},
								afterrender: function(ui) {
									ui.setValue("");
								},
								scope: this
							}
						},
						{
							xtype: "gridpanel",
							name: "fltypegrid",
							region: "center",
							layout: "fit",
							hideHeaders: true,
							flex: 1,
							height: 140,
							scroll: "vertical",
							stateful: false,
							store: {
								fields: [
									"selected", "name", "type", "nodepath", "uid", "iconimg"
								]
							},
							
							// stateful: true,
							
							columns: [
								{
									xtype: "checkcolumn",
									dataIndex: "selected",
									width: 30,
									editor: {
										xtype: "checkbox",
										cls: "x-grid-checkheader-editor"
									}
								},
								{	 
									header: "",  
									dataIndex: "iconimg",
									sortable: false,
									hideable: false,
									width: 20
								},
								{ 
									header: IRm$.r1("B_NAME"),  
									dataIndex: "name",
									sortable: false,
									hideable: false,
									flex: 1
								}
							],
							listeners: {
								afterrender: function(ui) {
								}
							}
						}
					],
					listeners: {
						
					}
				},
				{
					xtype: "fieldset",
					title: IRm$.r1("L_FLT_DATE_PERIOD"),
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: [
						{
							xtype: "checkbox",
							name: "fltsetdate",
							fieldLabel: "",
							boxLabel: IRm$.r1("B_ENABLED"),
							listeners: {
								change: function(field, newvalue, oldvalue, eOpt) {
									var checked = field.getValue(),
										fltfromdate = this.down("[name=fltfromdate]"),
										flttodate = this.down("[name=flttodate]");
									
									fltfromdate.setDisabled(!checked);
									flttodate.setDisabled(!checked);
								},
								scope: this
							}
						},
						{
							xtype: "datefield",
							name: "fltfromdate",
							disabled: true,
							labelWidth: 70,
							fieldLabel: IRm$.r1("B_FROM"),
							maxValue: new Date(),
							format: "Y-m-d",
							value: new Date()
						},
						{
							xtype: "datefield",
							name: "flttodate",
							disabled: true,
							labelWidth: 70,
							fieldLabel: IRm$.r1("B_TO"),
							maxValue: new Date(),
							format: "Y-m-d",
							value: new Date()
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				},
				{
					text: IRm$.r1('B_CLOSE'),
					handler: function() {
						this.close();
					},
					scope: this
				}
			]
		});
		
		IG$.explorerSearch.superclass.initComponent.apply(this, arguments);
	},
	listeners: {
		afterrender: function(tobj) {
			this.init_f();
		}
	}
});