IG$.formViewerEditor = $s.extend($s.window, {
	modal: true,
	region:'center',
	layout: {
		type: 'fit',
		align: 'stretch'
	},
	
	closable: true,
	resizable: true,
	width: 800,
	height: 600,
	
	_init: function() {
		var me = this,
			reportoption = me.reportoption._mc,
			sheetoption = me.sheetoption.model,
			items,
			i,
			dataquerymode = sheetoption.dataquerymode,
			mviewer = me.down("[name=_mviewer_]");
			
		sheetoption.formbuilder = sheetoption.formbuilder || {};
		
		me.setAllValues(sheetoption.formbuilder);
		sheetoption.formbuilder.item && me.down("[name=itemname]").setValue(sheetoption.formbuilder.item.name);
	},
	
	_confirm: function() {
		var me = this,
			reportoption = me.reportoption._mc,
			sheetoption = me.sheetoption.model,
			mviewer = me.down("[name=_mviewer_]");
		
		if (me.getAllValues(sheetoption.formbuilder))
			return;

		if (me.itemname && me.itemname.length)
		{
			sheetoption.formbuilder.item = me.itemname[0];
		}
		
		me.callback && me.callback.execute();
		me.close();
	},

	selectItem: function(sname) {
		var me = this;
		
		var dlgitemsel = new IG$.metaSelectDlg({
			instance: me.instance,
			visibleItems: "folder;dashboard",
			tree_options: {
				cubebrowse: false
			},
			callback: new IG$.callBackObj(me, function(item) {
				var me = this;
				me[sname] = [item];
				me.down("[name=" + sname + "]").setValue(item.name);
			})
		});
		
		IG$.checkLogin(this, dlgitemsel);
	},
	
	initComponent: function() {
		var me = this;
		
		$s.apply(me, {
			title: IRm$.r1("L_FORMVIEWER"),
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					border: 0,
					items: [
						{
							xtype: "fieldcontainer",
							fieldLabel: IRm$.r1("L_ITEM"),
							layout: "hbox",
							items: [
								{
									name: "itemname",
									xtype: "textfield",
									allowBlank: false,
									readOnly: true,
									emptyText: IRm$.r1("M_SEL_ITEM"),
									flex: 1
								},
								{
									xtype: "button",
									iconCls: "icon-toolbar-search",
									tooltip: IRm$.r1("B_SEARCH"),
									width: 20,
									handler: function() {
										this.selectItem("itemname");
									},
									scope: this
								}
							]
						}
					]
				}
			],
			buttons: [
				"->",
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: me
				}, 
				{
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: me
				}
			],
			listeners: {
				afterrender: function(tobj) {
					me._init();
				}
			}
		});
		
		IG$.formViewerEditor.superclass.initComponent.call(this);
	}
});

IG$.formViewer = $s.extend(IG$.v$pnl, {
	layout: "fit",
	
	_init: function() {
		var me = this;
		
		if (me._designmode)
		{
		}
		
		if (me.reportoption && me.sheetoption)
		{
			me.sheetoption.model.formbuilder = me.sheetoption.model.formbuilder || {};
			me._draw_area();
		}
	},
	
	_confirm: function() {
		var me = this,
			reportoption = me.reportoption._mc,
			sheetoption = me.sheetoption.model,
			formmodel = sheetoption.formbuilder;
		
		formmodel.items = [];
	},
	
	_draw_area: function() {
		var me = this,
			formview = me.down("[name=formview]"),
			req,
			formbuilder = me.sheetoption ? me.sheetoption.model.formbuilder : null;

		if (formbuilder && formbuilder.item)
		{
			me.setLoading(true);
					
			req = new IG$._rpc$();
			req.init(me, 
				{
					ack: "content",
					payload: {uid: formbuilder.item.uid},
					mbody: {}
				}, me, function(jdoc) {
					formview.rs_loadContent(jdoc);
					me._apply_data();
				}, false);
			req.send();
		}
	},
	
	$apply: function(result) {
		var me = this,
			formview = me.down("[name=formview]"),
			ctrl;
	},

	_apply_data: function() {
		var me = this,
			formview = me.down("[name=formview]"),
			mresults = me.$mresults,
			data = mresults ? mresults.results[0] : null;

		if (formview && data)
		{
			formview.$load_data(data, 0)
		}
	},
	
	applyReportResult: function(mresults, olapset, reportoption, sheetoption, lrender) {
		var me = this;
		me.$mresults = mresults;

		me._apply_data();
	},

	applyOptions: function(rop, sop) {
		var me = this;
		
		if (rop && sop)
		{
			me.reportoption = rop;
			me.sheetoption = sop;
		}
	},
	
	initComponent: function() {
		var me = this;
		
		$s.apply(me, {
			items: [
				new IG$.DashboardView({
					name: "formview",
					flex: 1,
					autoScroll: true
				})
			]
		});
		
		me.on("afterrender", function(tobj) {
			me._init();
		});
		
		IG$.formViewer.superclass.initComponent.call(this);
	}
});