

/**
 * fileupload control
 */
IG$._FC_fileupload = $s.extend(IG$._baseFC, {
	objtype: "fileupload",
	events: [
		{name: "change_val"}
	],
	create: function(container) {
		var me = this,
			fitem = me.fitem,
			fmodel = me.fmodel,
			fid = me._get_id(),
			ui = $("<div class='mec-fileupload-box'></div>")
				.appendTo(container),
			tin, tbtn;

		ui.addClass("form-outline");

		if (me.md)
		{
			lbl$ = me.lbl$ = $("<label class='form-label' for='" + fid + "'></label>"); // .appendTo(ui);
			// $("<div class='form-helper'></div>").appendTo(ui);
			me.mp$ = $("<md-outlined-text-field class='igc-md-ctrl idv-sel-flow-full' readonly='true'><md-icon slot='leading-icon'>upload_file</md-icon></md-outlined-text-field>").appendTo(ui);
			me.mp$.init();
		}
		else
		{
			tin = $("<input type='text' class='idv-checkbox-inp' id='" + fid + "'></input>").appendTo(ui);
			tin.addClass("form-control");
			tin.css({"float": "left"});
		}

		tbtn = $("<div class='idv-btn-selected'></div>").appendTo(ui);
			
		tbtn.bind("click", function(e) {
			e.stopPropagation();
			req = new IG$._rpc$();
			req.init(me,
				{
					ack: "helpcontent",
					payload: {uid: fmodel.uid},
					mbody: {option: "ftables"}
				}, me, function(jdoc) {
					var dlg = new IG$.dynfilterFileLoader({
						instance: me.instance,
						smode: fitem.smode,
						callback: new IG$.callBackObj(me, me.rs_checkPopup, fitem),
						filteritem: fitem,
						filetable: jdoc
					});
					IG$.checkLogin(this, dlg);
				});
			req.send();
		});
		
		return ui;
	},
	loadData: function(data) {
		var me = this,
			fitem = me.fitem;
		fitem.selection = [];
	},
	clear: function() {
		var me = this,
			ui = me.ui;
		if (me.md)
		{
			me.mp$.value = "";
		}
		else
		{
			$("input[type=text]", ui).val("");
		}
	},
	updateValue: function(value) {
		var me = this,
			fitem = me.fitem,
			selection;
			
		selection = fitem.selection = fitem.selection || [];
				
		if (selection.length)
		{
			value.push({code: selection[0].code, value: selection[0].value});
		}
	}
});

IG$.$FCinst["fileupload"] = new IG$._FC_fileupload();