/***********************************************************************
 * AppPageControl: Scheduler 
 */

IG$.ctrlScheduler = IG$.extend(IG$.ctrlBase, {
	type: "scheduler",

	initComponent: function() {
		var me = this,
			dsmode = me.dsmode;

		me.p.push(
			{name: "disabled", type: "property", datatype: "boolean", value: false}
		)
		
		me.superclass.prototype.initComponent.call(me);
	},

	updateProperty: function(kname, value) {
		var me = this,
			cmp$ = me.cmp$;
	},
	
	initDrawing: function () {
		var me = this,
			actionlist = me.ctrl.actionlist,
			property = me.property,
			owner = me.ctrl.owner,
			cmp$,
			lbl$,
            el$ = me.el$,
			fid = me._get_id(),
            mdiv;

        me.tl$.hide();

        if (!window.FullCalendar)
        {
            var js = [
                "./js/scheduler/index.global.min.js"
                ];
            
            IG$.ctrlScheduler._loading = 1;
            
            IG$.getScriptCache(
                js, 
                new IG$.callBackObj(this, function() {
                    IG$.ctrlScheduler._loaded = 1;
                    me.initDrawing();
                })
            );

            return;
        }

        el$.empty();

        mdiv = $("<div></div>").appendTo(el$);

        $cal = me.$cal = new FullCalendar.Calendar(mdiv[0], {
            initialView: "dayGridMonth",
            headerToolbar: { center: 'dayGridMonth,timeGridWeek' },
            views: {
                dayGridMonth: { // name of view
                    titleFormat: { year: 'numeric', month: '2-digit', day: '2-digit' }
                    // other view-specific options here
                }
            },
            dataClick: function(info) {
                void 0;
            },

        });

        $cal.render();

		me.superclass.prototype.initDrawing.call(me);
	},
	
	commit: function() {
		var me = this;
	},
	
	invalidate: function () {
	},
	
	getSelectionData: function(itemname) {
		var me = this;
		return null;
	}
});

IG$.controls.scheduler = new IG$.ctrlScheduler({}, null);