/**
 * calendar control
 */
IG$._FC_calendar = $s.extend(IG$._baseFC, {
	objtype: "calendar",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	create: function(container) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			sheetoption = me.sheetoption,
			dateseltype = fmodel.dateseltype,
			calendar_locale = IG$.calendar_locale,
			ui = $("<div class='mec-dateperiod-box form-outline'></div>")
				.appendTo(container),
			ys = fmodel.yearfrom || "cyear-5", 
			ye = fmodel.yearto || "cyear",
			dt,
			_init_value = fmodel._init_value || fmodel.initial_values,
			fid = me._get_id();
			
		ys = me.getYearField(ys);
		ye = me.getYearField(ye);
		
		if (dateseltype == "year")
		{
			var sel = [
				"<div class='mdc-select mdc-select--outlined igc-md-ctrl idv-sel-flow-full' placeholder='" + calendar_locale.c2disp + "'>",
				"	<div class='mdc-select__anchor' aria-labelledby='" + fid + "'>",
				"		<span class='mdc-notched-outline'>",
				"		<span class='mdc-notched-outline__leading'></span>",
				"		<span class='mdc-notched-outline__notch'>",
				"			<span id='" + fid + "' class='mdc-floating-label'>" + "</span>",
				"		</span>",
				"		<span class='mdc-notched-outline__trailing'></span>",
				"		</span>",
				"		<span class='mdc-select__selected-text-container'>",
				"		<span id='demo-selected-text' class='mdc-select__selected-text'></span>",
				"		</span>",
				"		<span class='mdc-select__dropdown-icon'>",
				"		<svg",
				"			class='mdc-select__dropdown-icon-graphic'",
				"			viewBox='7 10 10 5' focusable='false'>",
				"			<polygon",
				"				class='mdc-select__dropdown-icon-inactive'",
				"				stroke='none'",
				"				fill-rule='evenodd'",
				"				points='7 10 12 15 17 10'>",
				"			</polygon>",
				"			<polygon",
				"				class='mdc-select__dropdown-icon-active'",
				"				stroke='none'",
				"				fill-rule='evenodd'",
				"				points='7 15 12 10 17 15'>",
				"			</polygon>",
				"		</svg>",
				"		</span>",
				"	</div>",
				"	<div class='mdc-select__menu mdc-menu mdc-menu-surface mdc-menu-surface--fullwidth'>",
				"		<ul class='mdc-list' role='listbox'>",
				"		</ul>",
				"	</div>",
				"</div>"
			]
			me.mp$dv = $(sel.join('')).appendTo(ui)[0];
			dt = fitem.dt = me.mp$dv;
			lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$dv);
			me.mp$ = mdc.select.MDCSelect.attachTo(me.mp$dv);

			me.mp$dv.addEventListener("change", function() {
				me.trigger("change_val");
			});
			
			me._pop_dtval(fitem, dt, dateseltype, 1, _init_value);
			me.mp$.layoutOptions();
			me.mp$.placeholder = IRm$.r1("L_SELECT_VALUE");
		}
		else if (dateseltype == "month")
		{
			ptn = "yyyy-mm";
			
			fitem.dt = $("<input type='text'></input>")
				.css({
					position: "absolute",
					top: 0,
					bottom: 0,
					left: 0,
					width: 0,
					border: 0
				})
				.appendTo(ui);

			me.mp$dv = me.createTextField(ui, null);
			lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$dv);
			me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$dv);
			me.mp$.placeholder = calendar_locale.c2disp;
			fitem.dt.bind("change", function(e) {
				me.mp$.value = fitem.dt.val();
			});

			$(me.mp$dv).bind("click", function(e) {
				e.preventDefault();
				e.stopImmediatePropagation();
				fitem.dt.monthpicker("show");
				me._sync_val(me.mp$, fitem.dt, 0);
			});

			fitem.dt.monthpicker({
				constrainInput: false,
				monthNames: $.datepicker._defaults.monthNamesShort,
				buttonImageOnly: true,
				pattern: ptn,
				dateFormat: calendar_locale.c2format,
				startYear: ys,
				finalYear: ye
			});
			
			fitem.dt.bind("change", function() {
				me.trigger("change_val");
			});

			fitem.dt.bind("monthpicker-change-year", function(sender, year) {
				let v = fitem.dt.monthpicker("getDate");
				let nyear = parseInt(year);

				if (v && nyear > 0 && v.getYear() != nyear)
				{
					v.setYear(nyear);
					fitem.dt.monthpicker("setDate", v);
				}
			});
			
			_init_value && _init_value.length && me._pop_dtval(fitem, fitem.dt, dateseltype, 1, _init_value);

			$("<div class='mec-dateperiod-button idv-float-button'>&nbsp;</div>").appendTo(ui).bind("click", function() {
				fitem.dt.monthpicker("show");
				me._sync_val(me.mp$, fitem.dt, 0);
			});
		}
		else
		{
			me.mp$dv = me.createTextField(ui, null);
			lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$dv);
			me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$dv);
			me.mp$.placeholder = calendar_locale.c1disp;
			me.mp$dv.addEventListener("change", function(e) {
				if (fitem.dt.val() != me.mp$.value)
					fitem.dt.val(me.mp$.value);
			});

			fitem.dt = $("<input type='text'></input>")
				.css({
					position: "absolute",
					top: 0,
					bottom: 0,
					left: 0,
					width: 0,
					border: 0
				})
				.appendTo(ui);

			fitem.dt.startYear = ys;
			fitem.dt.finalYear = ye;
			
			IG$.dateUtil.createDatePicker(me, fitem.dt, function(dateText, inst) {
				me.trigger("change_val");
			});
			
			_init_value && _init_value.length && me._pop_dtval(fitem, fitem.dt, dateseltype, 1, _init_value);
			
			$("<div class='mec-dateperiod-button idv-float-button'>&nbsp;</div>").appendTo(ui).bind("click", function() {
				fitem.dt.datepicker("show");
				me._sync_val(me.mp$, fitem.dt, 0);
			});
		}
		
		return ui;
	},
	setValue: function(values, cmap, svalues) {
		var me = this,
			fitem = me.fitem,
			dateseltype = me.fmodel.dateseltype;
			
		if (dateseltype == "year")
		{
			me.mp$.value = values[0];
		}
		else if (dateseltype == "month")
		{
			fitem.dt.monthpicker("setDate", me.getDefaultDate(values[0]));
			if (me.mp$) me.mp$.value = fitem.dt.val();
		}
		else
		{
			fitem.dt.datepicker("setDate", me.getDefaultDate(values[0]));
			if (me.mp$) me.mp$.value = fitem.dt.val();
		}
	},
	updateValue: function(value) {
		var me = this,
			fitem = me.fitem,
			dateseltype = me.fmodel.dateseltype,
			v;
			
		if (dateseltype == "year")
		{
			v = me.mp$.value;
		}
		else if (dateseltype == "month")
		{
			v = fitem.dt.monthpicker("getDate");
		}
		else
		{
			v = fitem.dt.datepicker("getDate");
		}
		
		if (v)
		{
			if (dateseltype == "year")
			{
			}
			else
			{
				v = v.format("Ymd"); //  + "000000";
			}
			value.push({code: v, value: v, valuetype: "date", dateseltype: dateseltype});
		}
	},
	clear: function() {
		var me = this,
			fitem = me.fitem,
			dateseltype = me.fmodel.dateseltype;
		if (dateseltype == "year")
		{
			fitem.dt[0].value = "";
		}
		else if (dateseltype == "month")
		{
			if (me.mp$) me.mp$.value = "";
			fitem.dt.monthpicker("setDate", null);
		}
		else
		{
			if (me.mp$) me.mp$.value = "";
			fitem.dt.datepicker("setDate", null);
		}
	}
});

IG$.$FCinst["calendar"] = new IG$._FC_calendar();