/***********************************************************************
 * AppPageControl: File updload control
 */
 IG$.ctrlFileUpload = IG$.extend(IG$.ctrlBase, {
	type: "fileupload",
	doUpload: function() {
		var me = this,
			cmp$ = me.cmp$,
			mform = cmp$.down('[name=mform]'),
			orig_filename = cmp$.down("[name=orig_filename]"),
			photo = cmp$.down("[name=photo]"),
			req;
	
		if (mform.getForm().isValid()) {
			var f = mform.getForm();
			document.charset = "UTF-8";
			var fname = photo.getRawValue();
			if (fname.indexOf("\\") > -1)
			{
				fname = fname.substring(fname.lastIndexOf("\\")+1);
			}
			
			orig_filename.setValue(fname);
			
			mform.submit({
				url: ig$.servlet + "/upload",
				waitMsg: 'Uploading your data file',
				success: function(fp, o) {
					var node = fp.errorReader.jsonData,
						uid = node && node.result ? node.result.uid : null;
					
					me._result_uid = uid;
				}
			})
		}
	},
	initComponent: function() {
		var me = this;
		
		me.p.push(
			{name: "fieldlabel", type: "property", datatype: "string"},
			{name: "fileuploaded", type: "event"}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},

	initDrawing: function () {
		var me = this,
			el = me.el$,
			fileupload,
			d_progress,
			fid = me._get_id();
			
		me.fileupload = fileupload = $("<input type='file' class='form-control' id='" + fid + "'></input>").appendTo(el).hide();
		me.d_progress = d_progress = $("<div class='file-progress'><div class='bar' style='width: 0%;'></div></div>").appendTo(el);

		lbl$ = me.lbl$ = $("<label class='form-label' for='" + fid + "'>" + (me.property.fieldlabel || "") + "</label>"); //.appendTo(me.el$);
		me.tl$ && me.tl$.hide();

		me.mp$ = me.createTextField(me.el$, me.property.fieldLabel);
		$("<span class='mdc-text-field__affix mdc-text-field__affix--prefix'>FILE</span><i class='material-icons mdc-text-field__icon mdc-text-field__icon--leading' tabindex='0' role='button'>upload_file</i>").appendTo(me.mp$);
		lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$);

		$(me.mp$).click(function(e) {
			e.preventDefault();
			e.stopImmediatePropagation();

			me.fileupload.trigger("click");
		});

		me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$);

		me.fileupload.change(function(e) {
			me.mp$.value = me.fileupload.val();
		});

		// function _do_upload() {
			fileupload.fileupload({
				url: ig$.servlet + "/upload",
				dataType: "json",
				formData: {
					_mts_: IG$._g$a || ""
				},
				done: function (e, data) {
					void 0;
					me.__uploading = false;
					var jdoc = data.result || {errorcode: "0xffff", errormsg: "Server incorrect responding"},
						errcode = jdoc.errorcode,
						tnodes,
						i, dp = [], p, rec;
					
					if (errcode)
					{
						IG$.ShowErrorMessage(jdoc, me, null);
					}
					else
					{
						if (jdoc.result)
						{
							tnodes = jdoc.result.length ? jdoc.result : [jdoc.result];
							
							for (i=0; i < tnodes.length; i++)
							{
								p = tnodes[i];
								dp.push(p);
							}

							me.btn_upload[0].selected = true;
						}
					}
					
					if (dp && dp.length)
					{
						/*
						d_upfiles.show();
						
						for (i=0; i < dp.length; i++)
						{
							rec = d_upfiles.store.add(dp[i]);
							d_upfiles.selModel.select(rec, true);
						}
						*/
					}
				},
				progressall: function (e, data) {
					var progress = parseInt(data.loaded / data.total * 100, 10),
						bar = $(".bar", d_progress);
					bar.css(
						"width",
						progress + "%"
					);
					bar.text("Loaded " + data.loaded + " / " + data.total);
				}
			}).bind('fileuploadsubmit', function (e, data) {
			});
		// }

		// me.btn_upload = $("<md-filled-tonal-icon-button><md-icon>upload</md-icon><md-icon slot='selected'>check</md-icon></md-filled-tonal-icon-button>")
		// 	.appendTo(me.el$)
		// 	.bind("click", function(e) {
		// 		e.preventDefault();
		// 		e.stopImmediatePropagation();
		// 		if (me.__uploading)
		// 			return;
				
		// 		me.__uploading = true;
		// 		_do_upload();
		// 	});

		me.superclass.prototype.initDrawing.call(me);
	},
	
	invalidate: function () {
	},
	
	commit: function() {
		var me = this;
		// me.property["text"] = me.getValue();
	},
	
	getValue: function(param) {
		return null;
	}
});

IG$.controls.fileupload = new IG$.ctrlFileUpload({}, null);