/***********************************************************************
 * AppPageControl: Label 
 */
 IG$.ctrlLabel = IG$.extend(IG$.ctrlBase, {
	type: "label",
	initComponent: function() {
		var me = this;
		
		me.p.push(
			{name: "color", type: "property", datatype: "string"},
			{name: "fieldlabel", type: "property", datatype: "string"},
			{name: "fontbold", type: "property", datatype: "boolean"},
			{name: "fontsize", type: "property", datatype: "number", value: 12},
			{name: "text", type: "property", datatype: "string"}
		);
		
		me.tl$.hide();
		me.superclass.prototype.initComponent.call(me);
	},
	
	updateProperty: function(kname, value) {
		var me = this,
			cmp$ = me.cmp$;
		
		switch (kname)
		{
		case "text":
			cmp$ && cmp$.html(value);
			break;
		case "fontsize":
			if (value)
			{
				me.el$.css({fontSize: value + "px"});
			}
			break;
		case "fontbold":
			if (value == "true")
			{
				me.el$.css({fontWeight: "bold"});
			}
			else if (value == "false")
			{
				me.el$.css({fontWeight: "normal"});
			}
			break;
		case "color":
			if (value)
			{
				me.el$.css({color: value});
			}
			break;
		}
	},
	
	initDrawing: function() {
		var me = this;
		me.cmp$ = $("<div class='igc-ds-label'></div>").appendTo(me.el$);
		me.superclass.prototype.initDrawing.call(me);
	}
});

IG$.controls.label = new IG$.ctrlLabel({}, null);