/**
 * button control
 */
IG$._FC_button = $s.extend(IG$._baseFC, {
	objtype: "button",
	events: [
		{name: "button_click"}
	],
	properties: [
	],
	
	create: function(container) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			mcap = me.mcap,
			stext = fmodel.options.text || " ",
			ui;
			
		if (stext && stext.length > 1 && stext.charAt(0) == '{' && stext.charAt(stext.length-1) == '}')
		{
			stext = IRm$.r1(stext.substring(1, stext.length-1));
		}
		// ui = document.createElement("md-filled-tonal-button");
		ui = $("<button class='mdc-button mdc-button--raised'><span class='mdc-button__ripple'></span><span class='mdc-button__focus-ring'></span><span class='mdc-button__label'>" + stext + "</span></button>").appendTo(container)[0];
		mdc.iconButton.MDCIconButtonToggle.attachTo(ui);
		ui.value = IG$._rrcsv(stext);
		// ui.renderRoot.querySelector(".label").innerHTML = ui.value;
		ui.addEventListener("click", function() {
			me.trigger("button_click", fitem);
		});
		
		//mcap[0].classList.add("df-filter-sbutton");
		
		if (fmodel.options.action == "updateFilterValues")
		{
			me._sbtn = mcap;
			//ui.classList.add("dt-btn-search");
		}
		else if (fmodel.options.action == "f_bx")
		{
			me._sxbtn = mcap;
			mcap.hide();
			//ui.classList.add("dt-btn-download");
		}
		return $(ui);
	},
	
	$setProp: function(fitem, key, value) {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui;
			
		switch(key)
		{
		case "title":
			value = IRm$.r1(value);
			// $("span", ui).html(value);
			ui[0].value = value;
			$(".mdc-button__label", ui).html(value);
			fitem.u4.hide();
			return;
			break;
		}
		IG$._baseFC.prototype.$setProp.call(me, fitem, key, value);
	}
});

IG$.$FCinst["button"] = new IG$._FC_button();