IG$.SVGLoader = function(container, chart, owner) {
	var me = this;
	me.container = container;
	me.idfield = "id";
	me.mindex = 0;
	
	me.chart = chart;
	me.owner = owner;
	
	me.cop = owner && owner.cop ? owner.cop : null;
}

IG$.SVGLoader.prototype = {
	load: function(fname) {
		var me = this;
		if (me.loaded == fname)
		{
			me.resizeTo();
			$(me.container).trigger("svgloaded");
			return;
		}
		
		me.container.empty();
		
		$.ajax({
			url: fname,
			dataType: "text",
			type: "GET",
			cache: true,
			complete: function() {
			
			},
			success: function(data) {
				var xdoc = IG$.loadXML(data);
				me.loaded = fname;
				me.loadSVG(xdoc);
				$(me.container).trigger("svgloaded");
			},
			error: function() {
				
			}
		});	
	},
	
	loadSVG: function(xdoc) {
		var me = this,
			tnode,
			container = me.container,
			tparam,
			i,
			tfactor,
			vbox,
			paperdiv,
			textdiv;
		
		me.mapid = {};
		me.gparam = {
			cx: 0,
			cy: 0,
			cwidth: IG$.j$ext._w(container),
			cheight: IG$.j$ext._h(container),
			
			sx: 0,
			sy: 0,
			swidth: IG$.j$ext._w(container),
			sheight: IG$.j$ext._h(container)
		};
		
		me.text_elements = [];

		tnode = IG$.XGetNode(xdoc, "/svg");
		
		paperdiv = $("<div class='igc-svg-paper'></div>")
			.css({
				position: "relative"
			})
			.width("100%")
			.height("100%")
			.appendTo(container);
			
		textdiv = $("<div class='igc-svg-text-container'></div>")
			.css({
				position: "absolute",
				top: 0,
				left: 0,
				overflow: "visible"
			})
			.width(0)
			.height(0)
			.appendTo(container);
			
		me.paper = Raphael(paperdiv[0], 0, 0, me.gparam.cwidth, me.gparam.cheight);
		me.text_container = textdiv;
		
		if (me.cop && me.cop.settings)
		{
			me.line_color = me.cop.settings.m_svg_line_color;
			me.line_width = Number(me.cop.settings.m_svg_line_width);
			me.font_color = me.cop.settings.m_svg_font_color;
			me.font_size = Number(me.cop.settings.m_svg_font_size);
			me.label_opt = IG$._decodeVal(me.cop.settings.m_svg_label_option);
			me.nodatacolor = me.cop.settings.m_svg_nodata_color || "#ffffff";
		}
		
		me.line_color = me.line_color || "#000000";
		me.line_width = me.line_width || 2;
		me.font_color = me.font_color || "#ff0000";
		me.font_size = me.font_size || 20;
		me.nodatacolor = me.nodatacolor || "#ffffff";
		
		me.legend = $("<ul class='map-legend'></ul>").appendTo(container).hide();
		me.layer_info = $("<div class='igc-svglayer-info'><span id='igc-map-id'></span><div id='igc-map-info'></div></div>").appendTo(container);
		
		if (tnode)
		{
			tparam = IG$.XGetAttrProp(tnode);
			
			
			me.gparam.sx = (tparam.x) ? me.getVal(tparam.x) : me.gparam.sx;
			me.gparam.sy = (tparam.y) ? me.getVal(tparam.y) : me.gparam.sy;
			
			me.gparam.swidth = (tparam.width) ? me.getVal(tparam.width) : me.gparam.swidth;
			me.gparam.sheight = (tparam.height) ? me.getVal(tparam.height) : me.gparam.sheight;
			
			vbox = tparam.viewBox;
			vbox = (vbox) ? vbox.split(" ") : null;
			if (vbox)
			{
				for (i=0; i < vbox.length; i++)
				{
					vbox[i] = me.getVal(vbox[i]);
				}
				
				vbox = vbox[0] == me.gparam.sx && 
				vbox[1] == me.gparam.sy &&
				vbox[2] == me.gparam.swidth &&
				vbox[3] == me.gparam.sheight ? null : vbox;
			}
			
			me.gparam.vbox = vbox;
			
			me.paper.setSize(me.gparam.cwidth, me.gparam.cheight);
						
			var p = {
				isroot: true,
				id: null,
				children: [],
				childmap: {},
				d: [],
				set: me.paper.set()
			};

			me.recurseNode(tnode, p, tfactor);
			me.mainpage = p;
			
			/*
			var r = me.paper.rect(0, 0, me.gparam.swidth, me.gparam.sheight)
				.attr({
					"stroke": "#ff0000",
					"stroke-width": 2	
				});
				
			p.set.push(r);
			*/
			me.resizeTo();
		}
	},
	
	prepareLegend: function() {
		var me = this,
			legend = me.legend,
			mapseries = me.mapdata.measures;
			
		legend.empty();
		me.legidx = 0;
		if (mapseries && mapseries.length > 0)
		{
			legend.show();
			$.each(mapseries, function(i, map) 
			{
				$("<li class='map-legend-item'>" + (map.name || map.text) + "</li>")
					.appendTo(legend)
					.bind("click", function() {
						me.legidx = i;
						me.applyColor(i);
					});
			});
		}
		else
		{
			legend.hide();
		}
	},
	
	recurseNode: function(tnode, parent, tfactor) {
		var me = this,
			paper = me.paper, pval,
			tnodes = IG$.XGetChildNodes(tnode),
			text_container = me.text_container;
			
		$.each(tnodes, function(i, snode) {
			var nodename, p, path,
				text, text_div, tval,
				idfield = me.idfield || "id",
				idval;
			nodename = IG$.XGetNodeName(snode);
			pval = IG$.XGetAttrProp(snode);

			idval = pval[idfield] || pval.id || pval.name || "noid";
			
			if (nodename == "g")
			{
				p = {
					isroot: true,
					id: idval,
					name: idval,
					children: [],
					childmap: {},
					d: [],
					set: paper.set()
				};
				parent.set.push(p.set);
				parent.children.push(p);
				
				parent.childmap[idval] = p;
				me.mapid[idval] = {
					g: p
				};
				me.recurseNode(snode, p, tfactor);
			}
			else if (nodename == "path")
			{
				path = paper.path(pval.d)
					.attr({
						"fill": me.nodatacolor,
						"stroke-linejoin": "round",
						"stroke": me.line_color,
						"stroke-width": me.line_width
					});
				parent.d.push(path);
				delete pval.d;
				path.attr(path);
				parent.set.push(path);

				if (idval)
				{
					me.mapid[idval] = {
						g: path
					};
				}
				
				// path.transform(tfactor);
			}
			else if (nodename == "text")
			{
				tval = IG$.XGetTextVal(snode);
				text_div = $("<div class='igc-svg-text'></div>")
					.css({
						position: "absolute",
						top: Number(pval.y),
						left: Number(pval.x),
						fontSize: me.font_size,
						textAlign: "left",
						"white-space": "nowrap",
						color: me.font_color
					})
					.appendTo(text_container);
					
				text_div.html(tval);
				
				text = paper.text(Number(pval.x), Number(pval.y), "ksdjf")
					.attr({
						"font-size": me.font_size,
						"fill": me.font_color,
						"text-anchor": "middle",
						"alignment-baseline": "middle",
						"opacity": 0
					});
				parent.d.push(text);
				parent.set.push(text);
				
				var box = text.getBBox();
				var rect = paper.rect(box.x, box.y, box.width, box.height)
					.attr({
						// "fill": "#fff",
						"stroke": "#fff",
						opacity: 0.1
					});
				parent.set.push(rect);
				text.toFront();
				
				me.text_elements.push({
					paper: text,
					html: text_div
				})
				
				if (idval && tval && idval.charAt(0) == 'L' && me.mapid[idval.substring(1)])
				{
					me.mapid[tval] = me.mapid[idval.substring(1)];
					me.mapid[tval].t = text;
					me.mapid[tval].thtml = text_div;
				}
			}
		});
	},
	
	getVal: function(val) {
		val = val.replace(/px/, "");
		return Number(val);
	},
	
	_resize_text: function() {
		var me = this;
		
		$.each(me.text_elements, function(k, val) {
			var paper = val.paper,
				html = val.html;
				
			var box = paper.getBBox(),
				x = box.x,
				y = box.y,
				tw = html.width();
			
			html.css({
				top: y,
				left: x - tw / 2
			});
		});
	},
	
	resizeTo: function() {
		var me = this,
			container = me.container,
			scale,
			xscale, yscale,
			mscale = 1, mxscale=1, myscale=1,
			tfactor, mw, mh,
			vbox,
			cw, ch, sw, sh,
			p = me.mainpage;
		
		me.gparam.cwidth = IG$.j$ext._w(container);
		me.gparam.cheight = IG$.j$ext._h(container);
		
		vbox = me.gparam.vbox;
		
		cw = me.gparam.cwidth; 
		ch = me.gparam.cheight;
		sw = me.gparam.swidth; 
		sh = me.gparam.sheight;
			
		if (vbox)
		{
			mxscale = vbox[2] / sw;
			myscale = vbox[3] / sh;
			mscale = Math.min(mxscale, myscale);
		}
		
		xscale = cw / sw;
		yscale = ch / sh;
		scale = Math.min(xscale, yscale) * mscale;
		
		me.paper.setSize(cw, ch);
		
		mw = ((cw - sw * scale) / 2) / scale;
		mh = ((ch - sh * scale) / 2) / scale;
		tfactor = "s" + (scale) + "," + scale + ",0,0" + "t" + mw + "," + mh;
		
		p.set.transform(tfactor);
		
		me._resize_text();
	},
	
	loadData: function(chartoption) {
		var me = this;
		
		me.mapdata = chartoption;
		
		me.prepareLegend();
		
		me.applyColor(0);
	},
	
	applyColor: function(idx) {
		var me = this, i,
			min, max, mindex,
			maxdepth = 155,
			mapdata = me.mapdata,
			label_opt = me.label_opt,
			c, depth, mincolor = me.mapdata.m_svg_min_color || "#ffff51", 
			maxcolor = me.mapdata.m_svg_max_color || "#ff0000",
			nodatacolor = me.mapdata.m_svg_nodata_color || "#ffffff",
			legend = me.legend,
			layer_info = me.layer_info;
		
		me.legidx = idx;
		
		mindex = idx;
		mindex= (mindex < mapdata.measures.length) ? mindex : 0;
		
		legenditems = legend.children("li");
		
		if (legenditems && legenditems.length > 0)
		{
			for (i=0; i < legenditems.length; i++)
			{
				$(legenditems[i]).removeClass("map-legend-selected");
				if (i == mindex)
				{
					$(legenditems[i]).addClass("map-legend-selected");
				}
			}
		}
		
		if (mapdata.measures && mapdata.measures.length > mindex)
		{
			min = mapdata.measures[mindex].min;
			max = mapdata.measures[mindex].max;
			$.each(mapdata.point, function(i, pt) {
				var m = pt.data[mindex],
					path,
					path_t,
					path_thtml,
					n;
				if (isNaN(m))
				{
					path = me.mapid[i] ? me.mapid[i].g : null;
					
					path && path.attr({fill: nodatacolor});
				}
				else 
				{
					// depth = ((max - m) * maxdepth) / (max - min);
					depth = ((m - min) * maxdepth) / (max - min);
					c = IG$.interpolateColor(mincolor, maxcolor, maxdepth, depth);
					
					path = me.mapid[i] ? me.mapid[i].g : null;
					
					var _show_tooltip = function(path, e, is_html) {
						// path.attr("fill", "#ddd");
							
						var offset = me.container.offset(),
							x = is_html ? e.clientX - offset.left : e.offsetX + 5,
							y = is_html ? e.clientY - offset.top : e.offsetY + 5,
							tw = me.container.width(),
							th = me.container.height(),
							cw = 200,
							ch = 120;
							
						layer_info.css({
							top: th < y + ch ? th - ch : y,
							left: tw < x + cw ? tw - cw : x
						});
						
						clearTimeout(me._stimer);
						
						layer_info.show();
						
						var html = [];
						
						html.push("<div>* " + i + "</div>");
						html.push("<ul>");
						for (n=0; n < mapdata.measures.length; n++)
						{
							html.push("<li><span class='title'>" + mapdata.measures[n].text + ": </span> ");
							html.push(pt.text[n]);
							html.push("</li>");
						}
						html.push("</ul>");
						
						$("#igc-map-id", layer_info).html(html.join("\n"));
						
						me._stimer = setTimeout(function() {
							layer_info.fadeOut();
						}, 3000);
					} 
					
					if (path)
					{
						path.attr({fill: c});
						
						path.hover(function(e){
							path.$_oc = path.attr("fill");
							// path.attr("fill", "#efefef");
							_show_tooltip(path, e);
						}, function() {
							// path.attr("fill", path.$_oc);
						});
						
						path.mousedown(function(e) {
							_show_tooltip(path, e);
							
							var sender = {
									name: mapdata.measures[0].text
								},
								param = {
									point: {
										category: i
									}
								};
							$(me.container).trigger("region_clicked", {
								sender: sender, 
								param: param
							});
						});
					}
					
					path_t = me.mapid[i] ? me.mapid[i].t : null;
					
					if (path && path_t)
					{
						path_thtml = me.mapid[i].thtml;
						
						if (label_opt)
						{
							var lval = label_opt,
								dval = pt.text[mindex],
								mapid = pt.mapid;
								
							lval = lval.replace("{value}", dval);
							lval = lval.replace("{label}", mapid);
								
							path_thtml.html(lval);
							
							var box = path_t.getBBox(),
								x = box.x,
								y = box.y,
								tw = path_thtml.width();
							
							path_thtml.css({
								top: y,
								left: x - tw / 2
							});
						}
						
						path_thtml.hover(function(e) {
							// path.$_oc = path.attr("fill");
							// path.attr("fill", "#efefef");
							_show_tooltip(path, e, true);
						}, function() {
							// layer_info.fadeOut();
						});
						
						path_thtml.bind("click", function(e) {
							_show_tooltip(path, e, true);
							
							var sender = {
									name: mapdata.measures[0].text
								},
								param = {
									point: {
										category: i
									}
								};
							$(me.container).trigger("region_clicked", {
								sender: sender, 
								param: param
							});
						});
						
						/*
						path_t.hover(function(e){
							path.$_oc = path.attr("fill");
							// path.attr("fill", "#efefef");
							_show_tooltip(path, e);
						}, function(e) {
							// path.attr("fill", path.$_oc);
						});
						
						path_t.mousedown(function(e) {
							_show_tooltip(path, e);
							
							var sender = {
									name: mapdata.measures[0].text
								},
								param = {
									point: {
										category: i
									}
								};
							$(me.container).trigger("region_clicked", {
								sender: sender, 
								param: param
							});
						});
						*/
					}
				}
			});
		}
	}
};